import{_ as o,C as r,c as s,o as a,a3 as t,G as i}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Journal items","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/accounting-entries/journal-items.md","filePath":"master/finance/accounting-entries/journal-items.md","lastUpdated":1793074831000}'),l={name:"master/finance/accounting-entries/journal-items.md"};function g(c,e,m,u,d,h){const n=r("ImagePopup");return a(),s("div",null,[e[0]||(e[0]=t('<h1 id="journal-items" tabindex="-1">Journal items <a class="header-anchor" href="#journal-items" aria-label="Permalink to &quot;Journal items&quot;">​</a></h1><p>Journal items are the single lines of all journal entries, shown in one list. This is the place to ask questions like &quot;Which receivable lines are still open?&quot; or &quot;Show every line for one partner&quot;. The list is read only. You cannot add or change a line here.</p><blockquote><p><strong>In simple words:</strong> Journal Items is the full ledger list. Every debit and credit in the books is one row.</p></blockquote><p>Journal items exist in the Accounting app only. Open <code>Accounting → Journal Items</code>.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2>',5)),i(n,{src:"/images1/finance/journal_items_list.png",alt:"Journal Items list on the Posted view, showing the number, date, account, partner and label of each item"}),e[1]||(e[1]=t('<h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><ul><li><strong><em>Number:</em></strong> The number of the entry the line belongs to.</li><li><strong><em>Date:</em></strong> The accounting date.</li><li><strong><em>Account:</em></strong> The account, for example <strong>Account Receivable</strong>.</li><li><strong><em>Partner:</em></strong> The customer or vendor of the line.</li><li><strong><em>Label:</em></strong> The text of the line, for example <code>Manual Payment: INV/2026/2</code>.</li><li><strong><em>Reference:</em></strong> An outside reference.</li><li><strong><em>Journal:</em></strong> The journal of the entry.</li><li><strong><em>Debit</em></strong>, <strong><em>Credit</em></strong> and <strong><em>Balance</em>:</strong> The amounts. <strong>Balance</strong> is <strong>Debit</strong> minus <strong>Credit</strong>, so a credit shows a minus.</li></ul><p>More columns are hidden. Turn them on from the column toggle: <strong>Currency</strong>, <strong>Company</strong>, <strong>Status</strong>, <strong>Amount Currency</strong>, <strong>Amount Residual</strong>, <strong>Reconciled</strong> and <strong>Due Date</strong>.</p><p>At the bottom, <strong>Summary</strong> shows the totals for <strong>This page</strong> and for <strong>All Journal Items</strong>. The totals of <strong>Debit</strong> and <strong>Credit</strong> for all items are equal. In the sample data both are 71,070.</p><h2 id="saved-filters" tabindex="-1">Saved filters <a class="header-anchor" href="#saved-filters" aria-label="Permalink to &quot;Saved filters&quot;">​</a></h2><p>The tabs above the list are saved filters. <strong>Posted</strong> is the default.</p><ul><li><strong><em>Unposted:</em></strong> Lines of draft entries.</li><li><strong><em>Posted:</em></strong> Lines of posted entries.</li><li><strong><em>To Check:</em></strong> Lines of entries that are not marked <strong>Checked</strong>.</li><li><strong><em>Unreconciled:</em></strong> Lines that are not matched yet.</li><li><strong><em>With Residual:</em></strong> Lines that still have an open <strong>Amount Residual</strong>.</li><li><strong><em>Sales</em></strong>, <strong><em>Purchases</em></strong>, <strong><em>Bank</em></strong>, <strong><em>Cash</em></strong>, <strong><em>Credit</em></strong> and <strong><em>Miscellaneous:</em></strong> Lines of journals of that type.</li><li><strong><em>Payable:</em></strong> Lines on payable accounts. Use it to see what you owe.</li><li><strong><em>Receivable:</em></strong> Lines on receivable accounts. Use it to see what customers owe.</li><li><strong><em>P&amp;L Accounts:</em></strong> Lines on income and expense accounts.</li></ul><h2 id="group-filter-and-export" tabindex="-1">Group, filter and export <a class="header-anchor" href="#group-filter-and-export" aria-label="Permalink to &quot;Group, filter and export&quot;">​</a></h2><ul><li><strong>Group by:</strong> <strong>Journal Entry</strong>, <strong>Account</strong>, <strong>Partner</strong>, <strong>Journal</strong>, <strong>Date</strong>, <strong>Invoice Date</strong>, <strong>Matching</strong>, <strong>Status</strong> or <strong>Company</strong>.</li><li><strong>Filter:</strong> by number, label, reference, matching number, account, partner, journal, currency, dates, amounts, <strong>Reconciled</strong> and more.</li><li><strong>Export:</strong> Click <strong>Export</strong> to download the lines.</li></ul><p>See <a href="./../../getting-started/search-filter-group.html">Search, filter and group records</a>.</p><h2 id="matching-reconciled-and-amount-residual" tabindex="-1">Matching, Reconciled and Amount Residual <a class="header-anchor" href="#matching-reconciled-and-amount-residual" aria-label="Permalink to &quot;Matching, Reconciled and Amount Residual&quot;">​</a></h2><p>These three ideas show whether a line is settled.</p><ul><li><strong><em>Amount Residual:</em></strong> The part of a line that is still open. An unpaid invoice line has a residual equal to its amount. When a payment is matched, the residual falls to zero.</li><li><strong><em>Reconciled:</em></strong> Yes when the residual is zero. A matched line is reconciled.</li><li><strong><em>Matching:</em></strong> The group that links lines that settle each other. Group by <strong>Matching</strong> to see an invoice line and its payment line side by side.</li></ul><p>Example. Invoice <strong>INV/2026/2</strong> has a debit of $891.25 on <strong>Account Receivable</strong>. Payment <code>PBANK/2026/3</code> has a credit of $891.25 on the same account. They are matched, so both lines have a zero residual.</p><h2 id="common-tasks" tabindex="-1">Common tasks <a class="header-anchor" href="#common-tasks" aria-label="Permalink to &quot;Common tasks&quot;">​</a></h2><ul><li><strong>Find open customer debt:</strong> Open <strong>Receivable</strong>, then add <strong>With Residual</strong>.</li><li><strong>Find one customer lines:</strong> Search the partner name, then group by <strong>Account</strong>.</li><li><strong>See unreviewed entries:</strong> Open <strong>To Check</strong>.</li><li><strong>Find draft lines:</strong> Open <strong>Unposted</strong>.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>To fix a wrong line, open the journal entry from <code>Accounting → Journal Entries</code>. This list cannot edit.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./journal-entries.html">Journal entries</a></li><li><a href="./">Accounting entries overview</a></li><li><a href="./../reporting/general-ledger.html">General ledger</a></li></ul>',19))])}const b=o(l,[["render",g]]);export{f as __pageData,b as default};
